mapper.select:
SELECT ph.ph_no, DATE_FORMAT(ph.ph_date, '%Y-%m-%d %T') AS ph_date, ph.ph_email, ph.p_productId, ph.ph_count, ph.ph_payment, ph.pay_method, mp.mp_order, ph.ph_Refund_or_exchange AS ph_refund_or_exchange, p.title AS product_title, p.image AS product_image, sh.courier, sh.invoice_no FROM purchaseHistory ph LEFT JOIN myPage mp ON mp.ph_no = ph.ph_no LEFT JOIN product p ON p.productid = ph.p_productId LEFT JOIN shipment sh ON sh.ph_no = ph.ph_no
AND CAST(ph.ph_no AS CHAR) LIKE CONCAT('%', #{kw}, '%')
AND ph.ph_email LIKE CONCAT('%', #{kw}, '%')
AND ph.p_productId LIKE CONCAT('%', #{kw}, '%')
AND p.title LIKE CONCAT('%', #{kw}, '%')
AND mp.mp_order = #{status}
AND ph.ph_Refund_or_exchange = #{rex}
AND ph.ph_date >= CONCAT(#{from}, ' 00:00:00')
AND ph.ph_date <= CONCAT(#{to}, ' 23:59:59')
AND ph.pay_method = #{payMethod}
AND sh.courier = #{courier}
ORDER BY ph.ph_date DESC, ph.ph_no DESC
LIMIT #{limit}
OFFSET #{offset}

mapper.update:
UPDATE myPage
SET mp_order = #{status}
WHERE ph_no = #{phNo}
